Lemma vis Mq mdq LKq Awq crq kq a : INV Mq mdq LKq Awq crq kq a ->
  let MV := mrestrict (ahid Awq mdq) Mq in
  fstat MV sp /\ fov MV sp (PMSPA.o_v AD fb) (PESK.o_sink EE fb) /\ fcells R r MV sp
